var rows = Array.isArray(input) ? input : String(input || '').split(/\r?\n/).map(function (l) { return l.split(','); });
var seen = {}, out = [];
rows.forEach(function (r) {
  var clean, empty;
  if (Array.isArray(r)) { clean = r.map(function (c) { return String(c).trim(); }); empty = clean.join('') === ''; }
  else { clean = {}; empty = true; Object.keys(r || {}).forEach(function (k) { clean[k.trim()] = String(r[k]).trim(); if (clean[k.trim()] !== '') empty = false; }); }
  var key = JSON.stringify(clean);
  if (empty || (config.repeats === 'drop' && seen[key])) return;
  seen[key] = 1;
  out.push(clean);
});
console.log('kept ' + out.length + ' of ' + rows.length + ' rows');
return out;

