var t = typeof input === 'string' ? input : JSON.stringify(input || '');
var words = t.toLowerCase().match(/[a-z0-9\u00C0-\uFFFF']+/g) || [];
var count = {};
words.forEach(function (w) { if (w.length > 3) count[w] = (count[w] || 0) + 1; });
var top = Object.keys(count).sort(function (a, b) { return count[b] - count[a] || (a < b ? -1 : 1); }).slice(0, Number(config.top));
var out = [
  { measure: 'Words', value: words.length },
  { measure: 'Characters', value: t.length },
  { measure: 'Sentences', value: (t.match(/[.!?]+(\s|$)/g) || []).length },
  { measure: 'Minutes to read', value: Math.max(1, Math.round(words.length / 220)) }
];
top.forEach(function (w) { out.push({ measure: 'Uses of ' + w, value: count[w] }); });
return out;

var hexes = Array.isArray(input) ? input : (String(input || '').match(/#[0-9a-fA-F]{6}\b|#[0-9a-fA-F]{3}\b/g) || []);
var lum = function (h) {
  h = h.replace('#', '');
  if (h.length === 3) h = h.charAt(0) + h.charAt(0) + h.charAt(1) + h.charAt(1) + h.charAt(2) + h.charAt(2);
  var c = [0, 2, 4].map(function (i) { var v = parseInt(h.substr(i, 2), 16) / 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); });
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
};
var need = Number(config.level), out = [];
for (var i = 0; i < hexes.length; i++) {
  for (var j = i + 1; j < hexes.length; j++) {
    var a = lum(hexes[i]), b = lum(hexes[j]), ratio = (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
    out.push({ color: hexes[i], on: hexes[j], ratio: Math.round(ratio * 100) / 100, result: ratio >= need ? 'Pass' : 'Fail' });
  }
}
if (!out.length) throw new Error('Connect a Palette with at least two colors');
return out;

var lines = String(input || '').split(/\r?\n/), out = ['# Outline', ''], n = 0;
lines.forEach(function (l) {
  var m = /^(#{1,3})\s+(.*)$/.exec(l.trim());
  if (m) { n++; out.push((m[1].length === 1 ? '- ' : '- ' + new Array(m[1].length).join('› ')) + m[2]); }
});
if (!n) throw new Error('No headings found. Headings start with #.');
return out.join('\n');

var ids = Object.keys(inputs);
if (ids.length < 2) throw new Error('Connect two texts to compare');
var a = String(inputs[ids[0]]).split(/\r?\n/), b = String(inputs[ids[1]]).split(/\r?\n/), inB = {}, inA = {}, out = [];
b.forEach(function (l) { inB[l] = 1; });
a.forEach(function (l) { inA[l] = 1; });
a.forEach(function (l) { if (!inB[l]) out.push('- ' + l); });
